import json

import boto3

from embeddings_client import get_bedrock_client
from embeddings_models import normalize_response


def embedding_job_summary(job_id, config=None):
    config = config or {}
    client = get_bedrock_client(config)
    response = client.get_embedding_job(jobId=job_id)
    stream = response['body']
    try:
        return normalize_response(json.loads(stream.read()))
    finally:
        stream.close()

import re


def corpus_safety(text):
    if re.search(r'[a-zA-Z]', text):
        return {"safe": True}
    else:
        return {"safe": False}

import boto3


def multilingual_query_translate(query, target_language, config=None):
    config = config or {}
    client = boto3.client('translate', region_name=config.get('region', 'us-east-1'))
    response = client.translate_text(Text=query, SourceLanguageCode='auto', TargetLanguageCode=target_language)
    return {"translated_query": response['TranslatedText']}

import boto3


def retrieval_audio_brief(search_results, config=None):
    config = config or {}
    client = boto3.client('polly', region_name=config.get('region', 'us-east-1'))
    speech = ' '.join([result['text'] for result in search_results])
    response = client.synthesize_speech(Text=speech, OutputFormat='mp3', VoiceId='Joanna')
    with open('audio_brief.mp3', 'wb') as file:
        file.write(response['AudioStream'].read())
    return {"audio_brief": 'audio_brief.mp3'}
